            r->offset += 2; return 1;
        /* 17 is a NODE INDEX (docs/SPEC-TABLES.md 3.1): four bytes, so it costs
           one row here and a reader without the kind still skips a pointer field */
        case 4: case 8: case 10: case 17:
            if ( !table_reader_has( r, 4 ) ) { return 0; }
            r->offset += 4; return 1;
